<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Samsung Galaxy Ecosystem 2025</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;800&family=Inter:wght@400;600&display=swap');

  :root {
    --bg-navy: #030b1c;
    --samsung-blue: #1428a0;
    --accent-blue: #3b82f6;
    --gold: #d4af37;
    --silver: #e2e8f0;
    --white: #ffffff;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    padding: 0;
    background: linear-gradient(135deg, var(--bg-navy) 0%, #0a192f 100%);
    color: var(--white);
    font-family: 'Inter', sans-serif;
    width: 1080px;
    height: 1920px;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  h1, h2, h3 { font-family: 'Montserrat', sans-serif; margin: 0; }

  /* Header & Hero Zone */
  .hero-zone {
    text-align: center;
    padding: 60px 40px;
    position: relative;
    background: radial-gradient(circle at top, rgba(59, 130, 246, 0.2) 0%, transparent 60%);
  }

  .title {
    font-size: 52px;
    font-weight: 800;
    letter-spacing: -1px;
    margin-bottom: 20px;
    text-transform: uppercase;
  }

  .subtitle {
    font-size: 24px;
    color: var(--silver);
    font-weight: 400;
    max-width: 800px;
    margin: 0 auto 50px auto;
  }

  .hero-products {
    display: flex;
    justify-content: center;
    gap: 40px;
    margin-top: 30px;
  }

  .product-card {
    background: rgba(20, 40, 160, 0.2);
    border: 1px solid rgba(59, 130, 246, 0.3);
    border-radius: 20px;
    padding: 30px;
    width: 380px;
    backdrop-filter: blur(10px);
    position: relative;
    overflow: hidden;
  }

  .product-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; height: 4px;
    background: linear-gradient(90deg, var(--gold), #facc15);
  }

  .badge-new {
    position: absolute;
    top: 20px;
    right: 20px;
    background: linear-gradient(135deg, var(--gold), #f59e0b);
    color: #000;
    padding: 6px 14px;
    border-radius: 30px;
    font-weight: 800;
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .product-card h3 {
    font-size: 32px;
    margin-top: 10px;
    margin-bottom: 10px;
    color: var(--white);
  }

  .product-card p {
    color: var(--silver);
    font-size: 18px;
    margin: 0;
  }

  /* Metrics Zone */
  .metrics-zone {
    display: flex;
    justify-content: center;
    gap: 30px;
    padding: 20px 60px;
    margin-top: -20px;
    z-index: 10;
  }

  .metric-block {
    background: rgba(255,255,255,0.05);
    border-radius: 15px;
    padding: 20px;
    text-align: center;
    flex: 1;
    border: 1px solid rgba(255,255,255,0.1);
  }

  .metric-value {
    font-family: 'Montserrat', sans-serif;
    font-size: 42px;
    font-weight: 800;
    color: var(--accent-blue);
    margin-bottom: 5px;
  }

  .metric-label {
    font-size: 16px;
    color: var(--silver);
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  /* Infographic Overview Middle */
  .overview-zone {
    flex: 1;
    padding: 20px 60px;
    display: flex;
    flex-direction: column;
  }

  .overview-title {
    text-align: center;
    font-size: 36px;
    margin-bottom: 20px;
    color: var(--gold);
  }

  .infographic-container {
    flex: 1;
    width: 100%;
    position: relative;
    background: rgba(0, 0, 0, 0.2);
    border-radius: 20px;
    padding: 20px;
    border: 1px solid rgba(255,255,255,0.05);
  }

  /* Category Table Bottom */
  .table-zone {
    padding: 40px 60px 60px 60px;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    background: rgba(20, 40, 160, 0.1);
    border-radius: 15px;
    overflow: hidden;
    border: 1px solid rgba(59, 130, 246, 0.2);
  }

  th, td {
    padding: 20px;
    text-align: left;
    border-bottom: 1px solid rgba(255,255,255,0.05);
  }

  th {
    background: rgba(59, 130, 246, 0.1);
    font-family: 'Montserrat', sans-serif;
    font-size: 20px;
    color: var(--silver);
    text-transform: uppercase;
  }

  td {
    font-size: 20px;
  }

  .status-new {
    color: var(--gold);
    font-weight: 800;
    letter-spacing: 1px;
  }

  .status-current {
    color: var(--accent-blue);
  }

  .ai-branding {
    text-align: center;
    font-size: 22px;
    font-weight: 600;
    color: var(--silver);
    margin-top: 20px;
    letter-spacing: 1px;
  }
</style>
</head>
<body>

  <div class="hero-zone">
    <h1 class="title">Samsung Galaxy Ecosystem 2025</h1>
    <p class="subtitle">Innovation Across Every Category. Spanning smartphones, foldables, wearables, audio, and smart home — all powered by AI.</p>

    <div class="hero-products">
      <div class="product-card">
        <div class="badge-new">NEW</div>
        <h3>Galaxy S26 Ultra</h3>
        <p>Flagship Smartphone<br>with Pro-Grade Cameras & Galaxy AI</p>
      </div>
      <div class="product-card">
        <div class="badge-new">NEW</div>
        <h3>Galaxy Buds4 Pro</h3>
        <p>High-Fidelity Audio<br>with Next-Gen Active Noise Cancellation</p>
      </div>
    </div>
  </div>

  <div class="metrics-zone">
    <div class="metric-block">
      <div class="metric-value">7+</div>
      <div class="metric-label">Product Categories</div>
    </div>
    <div class="metric-block">
      <div class="metric-value">14</div>
      <div class="metric-label">Featured Products</div>
    </div>
    <div class="metric-block">
      <div class="metric-value">2</div>
      <div class="metric-label">Flagship Launches</div>
    </div>
    <div class="metric-block">
      <div class="metric-value">4+</div>
      <div class="metric-label">AI-Branded Devices</div>
    </div>
  </div>

  <div class="overview-zone">
    <h2 class="overview-title">AI-Powered Everything</h2>
    <div class="infographic-container" id="container"></div>
  </div>

  <div class="table-zone">
    <table>
      <thead>
        <tr>
          <th>Category</th>
          <th>Featured Product</th>
          <th>Status</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td>Smartphones</td>
          <td>Galaxy S26 Ultra</td>
          <td class="status-new">NEW</td>
        </tr>
        <tr>
          <td>Foldables & Tablets</td>
          <td>Galaxy Z Fold7 / Flip7 / Tab S11</td>
          <td class="status-current">Current</td>
        </tr>
        <tr>
          <td>Wearables & Audio</td>
          <td>Watch Ultra / Buds4 Pro</td>
          <td class="status-new">NEW Audio</td>
        </tr>
        <tr>
          <td>Home & Entertainment</td>
          <td>Neo QLED 8K / The Frame / Q-Soundbar</td>
          <td class="status-current">Current</td>
        </tr>
        <tr>
          <td>Smart Appliances</td>
          <td>Bespoke AI Refrigerator / Laundry / Vacuums</td>
          <td class="status-current">Current</td>
        </tr>
      </tbody>
    </table>
    <div class="ai-branding">Powered by <strong>Bespoke AI</strong> & <strong>Galaxy AI</strong></div>
  </div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
  const infographic = new AntVInfographic.Infographic({
    container: '#container',
    width: '100%',
    height: '100%',
  });
  infographic.render(`infographic list-grid-badge-card
data
  title The Complete Galaxy Ecosystem
  desc 14 featured products seamlessly unified
  lists
    - label 📱 Mobile Intelligence
      value Galaxy AI
      desc S26 Ultra, Fold7, Flip7
      icon magic
    - label 🏠 Smart Home
      value Bespoke AI
      desc AI Refrigerator, AI Laundry
      icon home
    - label 📺 Entertainment
      value 8K Visuals
      desc Neo QLED, The Frame Pro
      icon monitor
    - label 🎧 Personal Audio
      value Pro Sound
      desc Buds4 Pro, Watch Ultra
      icon sound
theme
  palette #1e3a8a #3b82f6 #d4af37 #030b1c`);
</script>
</body>
</html>
EOF
